={{ (() => {
  const src = $('When Executed by Another Workflow').first().json;
  const grupo = String(src.grupo || '').replace(/\D/g, '');
  const orden = String(src.orden || '').replace(/\D/g, '');
  if (grupo && orden && String(src.grupo || '').trim() !== '-' && String(src.orden || '').trim() !== '-') return true;
  const clave = String(src.clave || '').trim();
  if (/(\d+)\s*\/\s*(\d+)/.test(clave)) return true;
  if (/^d\d{6,9}$/i.test(clave) || /^\d{7,9}$/.test(clave)) return true;
  return false;
})() }}

assignments.value:
={{ (() => {
  function fromNode(name) {
    try {
      const item = $(name).first();
      if (!item || !item.json || typeof item.json.data !== 'string') return '';
      const parsed = JSON.parse(item.json.data);
      if (!Array.isArray(parsed) || parsed.length !== 1) return '';
      const grupo = String(parsed[0].Grupo ?? '').replace(/\D/g, '');
      const orden = String(parsed[0].Orden ?? '').replace(/\D/g, '');
      if (grupo && orden) return grupo + '/' + orden;
      return '';
    } catch (e) {
      return '';
    }
  }
  const fromPhone = fromNode('Buscar tel empresa 8') || fromNode('Buscar tel empresa 3');
  if (fromPhone) return fromPhone;
  const src = $('When Executed by Another Workflow').first().json;
  const rawGrupo = String(src.grupo || '').trim();
  const rawOrden = String(src.orden || '').trim();
  const grupo = rawGrupo.replace(/\D/g, '');
  const orden = rawOrden.replace(/\D/g, '');
  if (grupo && orden && rawGrupo !== '-' && rawOrden !== '-') return grupo + '/' + orden;
  const clave = String(src.clave || '').trim();
  if (!clave || clave === '-' || clave.toLowerCase() === 'undefined') return '';
  const match = clave.match(/(\d+)\s*\/\s*(\d+)/);
  if (match) return match[1] + '/' + match[2];
  return clave.replace(/\s+/g, '');
})() }}

